entity fifo_async is
    generic (
        FIFO_DEPTH_IN_BITS: natural range 0 to to_bits(natural'high) := 2;
        CDC_SYNC_STAGES: positive := 2;
        INTEL_DEVICE_FAMILY: string := "Cyclone V"; -- Change this to your target Intel device family
